@Override
@Transactional
public ServiceResult submitSensorSample(String raceId, String bib, SubmitSensorSampleRequest request) {
    return withIdempotency(request.requestId(), "SUBMIT_SENSOR_SAMPLE",
            orderedParams(
                    "raceId", raceId,
                    "bib", bib,
                    "sampleId", request.sampleId(),
                    "checkpointCode", request.checkpointCode(),
                    "sensorId", request.sensorId(),
                    "elapsedMillis", request.elapsedMillis(),
                    "operator", request.operator(),
                    "expectedVersion", request.expectedVersion()),
            () -> {
                // sampleId 第二层幂等
                SensorSampleRow existing = repository.findSensorSample(request.sampleId()).orElse(null);
                if (existing != null) {
                    return replaySampleOrConflict(raceId, bib, request, existing);
                }
                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                requireRunner(raceId, bib);
                CheckpointRow checkpoint = requireSensorCheckpoint(raceId, request.checkpointCode());
                List<SensorSampleRow> samples = repository.findSensorSamples(raceId, bib, request.checkpointCode());
                boolean sensorExists = samples.stream().anyMatch(s -> s.sensorId().equals(request.sensorId()));
                if (sensorExists) {
                    throw new UnprocessableEntityException("该传感器已登记读数，须通过修订接口变更: " + request.sensorId());
                }
                if (samples.size() >= SensorQuorum.REQUIRED_SENSORS) {
                    throw new UnprocessableEntityException("同一选手同一检查点最多三个传感器读数");
                }
                bumpVersion(race, request.expectedVersion());
                long now = clock.millis();
                SensorSampleRow row = new SensorSampleRow(request.sampleId(), raceId, bib,
                        request.checkpointCode(), request.sensorId(), 1, request.elapsedMillis(),
                        request.operator(), now, now);
                try {
                    repository.insertSensorSample(row);
                } catch (DuplicateKeyException ex) {
                    if (constraintMatches(ex, "pk_sensor_sample")) {
                        SensorSampleRow concurrent = repository.findSensorSample(request.sampleId()).orElseThrow();
                        return replaySampleOrConflict(raceId, bib, request, concurrent);
                    }
                    throw new UnprocessableEntityException("该传感器已登记读数，须通过修订接口变更: " + request.sensorId());
                }
                SensorSampleRow saved = repository.findSensorSample(request.sampleId()).orElseThrow();
                return ServiceResult.created(ResponseMapper.toSensorSampleResponse(saved));
            });
}
```

