                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                RunnerRow runner = requireRunner(raceId, bib);
                CheckpointRow checkpoint = requireSensorCheckpoint(raceId, request.checkpointCode());
                List<SensorSampleRow> samples = repository.findSensorSamples(raceId, bib, request.checkpointCode());
                SensorQuorum.QuorumResult quorum = SensorQuorum.adjudicate(samples);
                if (!quorum.accepted()) {
                    throw new UnprocessableEntityException(quorum.violation());
                }
                long median = quorum.medianMillis();
                List<CheckpointTimingRow> runnerTimings = repository.findTimingsForRunner(raceId, bib);
                String violation = CheckpointRules.validate(runnerTimings, checkpoint.position(), median, runner.finishTimeMs());
                if (violation != null) {
